import React, { useState } from 'react';
import { Plus, FolderPlus, CheckCircle2, Loader2 } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '../../api/client';
import { useProjects } from '../../hooks/useProjects';
import { Project } from '../../types';

export const ProjectView: React.FC = () => {
  const [name, setName] = useState('');
  const [deleteId, setDeleteId] = useState('');
  const [logs, setLogs] = useState<string[]>([]);
  const queryClient = useQueryClient();
  const { data: projects } = useProjects();

  const createMutation = useMutation({
    mutationFn: async (projectName: string) => {
      const formData = new FormData();
      formData.append('name', projectName);
      const response = await apiClient.post('/projects/create', formData);
      return response.data;
    },
    onSuccess: (data) => {
      setLogs(data.logs || [`SUCCESS: Project ready.`]);
      setName('');
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
    onError: (error: any) => {
      const msg = error.response?.data?.detail || error.message;
      setLogs([...logs, `ERROR: ${msg}`]);
    }
  });

  const deleteMutation = useMutation({
    mutationFn: async (projectId: string) => {
      const response = await apiClient.delete(`/projects/${projectId}`);
      return response.data;
    },
    onSuccess: (data) => {
      setLogs(data.logs || [`SUCCESS: Project deleted.`]);
      setDeleteId('');
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
    onError: (error: any) => {
      const msg = error.response?.data?.detail || error.message;
      setLogs([...logs, `ERROR: ${msg}`]);
    }
  });

  const handleCreate = () => {
    if (!name) return;
    setLogs([`Initializing project "${name}"...`]);
    createMutation.mutate(name);
  };

  const handleDelete = () => {
    if (!deleteId) return;
    if (confirm(`PERMANENT ACTION: Are you sure you want to delete "${deleteId}"? This will remove all files, configurations and results associated with this project.`)) {
      setLogs([`Deleting project "${deleteId}"...`]);
      deleteMutation.mutate(deleteId);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-12">
      {/* Creation Section */}
      <div className="space-y-8">
        <div className="text-center">
          <div className="w-16 h-16 bg-neutral-800 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <FolderPlus className="w-8 h-8 text-green-500" />
          </div>
          <h2 className="text-3xl font-bold">New Project</h2>
          <p className="text-neutral-500 mt-1">Scaffold a new analysis workspace.</p>
        </div>

        <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-8 space-y-6">
          <div>
            <label className="text-sm font-bold uppercase tracking-widest text-neutral-500 mb-2 block">Project Identity</label>
            <div className="flex gap-3">
              <input 
                type="text" 
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. ProjectAlpha_2025"
                disabled={createMutation.isPending}
                className="flex-1 bg-neutral-950 border border-neutral-800 rounded-xl px-4 py-3 focus:outline-none focus:border-green-600 transition-all text-lg disabled:opacity-50"
              />
              <button 
                onClick={handleCreate}
                disabled={!name || createMutation.isPending}
                className="px-6 bg-green-600 hover:bg-green-500 disabled:bg-neutral-800 disabled:text-neutral-600 rounded-xl font-bold transition-all flex items-center gap-2"
              >
                {createMutation.isPending ? <Loader2 className="w-5 h-5 animate-spin" /> : <Plus className="w-5 h-5" />}
                CREATE
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Administration Section */}
      <div className="space-y-8">
        <div className="text-center">
          <h2 className="text-xl font-bold text-neutral-400">Project Administration</h2>
          <p className="text-xs text-neutral-600 mt-1 uppercase tracking-widest">Permanent Actions</p>
        </div>

        <div className="bg-red-950/10 border border-red-900/20 rounded-2xl p-8 space-y-6">
          <div>
            <label className="text-[10px] text-red-500/70 uppercase font-bold mb-2 block tracking-tighter">Danger Zone: Remove Project</label>
            <div className="flex gap-3">
              <select 
                value={deleteId}
                onChange={(e) => setDeleteId(e.target.value)}
                className="flex-1 bg-neutral-950 border border-red-900/20 rounded-xl px-4 py-3 focus:outline-none focus:border-red-600 transition-all text-neutral-300"
              >
                <option value="">Select project to delete...</option>
                {projects?.map((p: Project) => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
              <button 
                onClick={handleDelete}
                disabled={!deleteId || deleteMutation.isPending}
                className="px-6 bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white border border-red-600/30 rounded-xl font-bold transition-all text-xs disabled:opacity-30"
              >
                {deleteMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : 'DELETE PERMANENTLY'}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Activity Log */}
      {logs.length > 0 && (
        <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-6 space-y-2">
          <h3 className="text-[10px] font-bold uppercase text-neutral-600 ml-1">Activity Log</h3>
          <div className="bg-black/40 rounded-xl p-4 font-mono text-xs border border-neutral-800/50 max-h-40 overflow-auto">
            {logs.map((log, i) => (
              <div key={i} className="flex items-center gap-2 mb-1 text-neutral-400">
                {i === logs.length - 1 && <CheckCircle2 className="w-3 h-3 text-green-500" />}
                <span>{log}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useRef, useState } from 'react';
import { FileCheck, FileX, Plus, Trash2, Image as ImageIcon, Upload, Loader2, ChevronDown } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '../../api/client';

interface FilePlacerProps {
  projectId: string;
}

export const FilePlacer: React.FC<FilePlacerProps> = ({ projectId }) => {
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const filesInputRef = useRef<HTMLInputElement>(null);
  const [activeUpload, setActiveUpload] = useState<{ category: string, layerKey?: string } | null>(null);

  const { data: projectFiles, isLoading } = useQuery({
    queryKey: ['project-files', projectId],
    queryFn: async () => {
      const response = await apiClient.get(`/projects/${projectId}/files`);
      return response.data;
    }
  });

  const { data: validationData, isLoading: isValidating } = useQuery({
    queryKey: ['validation', projectId],
    queryFn: async () => (await apiClient.get(`/projects/${projectId}/dataset/validate-checker`)).data,
    enabled: !!projectFiles?.config_files.find((f: any) => f.category === 'ideal_checker' && f.exists),
    retry: false
  });

  const deleteMutation = useMutation({
    mutationFn: async (filename: string) => {
      await apiClient.delete(`/projects/${projectId}/dataset/calibration_images/${filename}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
      queryClient.invalidateQueries({ queryKey: ['validation', projectId] });
    }
  });

  const deleteAssetMutation = useMutation({
    mutationFn: async (filename: string) => {
      await apiClient.delete(`/projects/${projectId}/assets/${filename}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
    }
  });

  const uploadMutation = useMutation({
    mutationFn: async ({ file, category, layerKey, parentAssetId }: { file: File, category: string, layerKey?: string, parentAssetId?: string }) => {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('category', category);
      if (layerKey) formData.append('layer_key', layerKey);
      if (parentAssetId) formData.append('parent_asset_id', parentAssetId);
      await apiClient.post(`/projects/${projectId}/files/upload`, formData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
      queryClient.invalidateQueries({ queryKey: ['validation', projectId] });
      setActiveUpload(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  });

  const linkMutation = useMutation({
    mutationFn: async ({ filename, parentAssetId }: { filename: string, parentAssetId: string }) => {
      const formData = new FormData();
      formData.append('parent_asset_id', parentAssetId);
      await apiClient.post(`/projects/${projectId}/dataset/calibration_images/${filename}/link`, formData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
    }
  });

  // Group calibration images
  const groupedImages: Record<string, any[]> = {};
  projectFiles?.calibration_images?.forEach((img: any) => {
    const gid = img.parent_asset_id || 'none';
    if (!groupedImages[gid]) groupedImages[gid] = [];
    groupedImages[gid].push(img);
  });

  const handleUploadClick = (category: string, layerKey?: string) => {
    if (fileInputRef.current) fileInputRef.current.value = '';
    setActiveUpload({ category, layerKey });
    setTimeout(() => fileInputRef.current?.click(), 10);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUpload) {
      uploadMutation.mutate({
        file: e.target.files[0],
        category: activeUpload.category,
        layerKey: activeUpload.layerKey
      });
    }
  };

  const handleAddImagesClick = () => {
    filesInputRef.current?.click();
  };

  const handleMultiFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      for (const file of files) {
        try {
          await uploadMutation.mutateAsync({ file, category: 'calibration_image' });
        } catch (err) { console.error(err); }
      }
    }
    if (filesInputRef.current) filesInputRef.current.value = '';
    e.target.value = '';
  };

  const handleDeleteImage = (filename: string) => {
    if (confirm(`Are you sure you want to delete ${filename}?`)) {
      deleteMutation.mutate(filename);
    }
  };

  const handleDeleteAsset = (filename: string) => {
    if (confirm(`Are you sure you want to delete asset ${filename}?`)) {
      deleteAssetMutation.mutate(filename);
    }
  };

  const handleLinkChange = (filename: string, parentId: string) => {
    linkMutation.mutate({ filename, parentAssetId: parentId });
  };

  const getFullUrl = (path?: string, category?: string) => {
    // Determine backend root (e.g., http://localhost:8000)
    const apiBase = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000/api';
    const baseUrl = apiBase.replace(/\/api$/, '');

    if (category === 'ideal_checker') {
      return `${baseUrl}/data/reference_images/global_TEOGRIM_reference.png`;
    }
    if (!path) return '';
    if (path.startsWith('http')) return path;

    // Ensure path starts with / if it's relative
    const normalizedPath = path.startsWith('/') ? path : `/${path}`;
    return `${baseUrl}${normalizedPath}`;
  };

  if (isLoading) return <div className="flex justify-center p-10"><Loader2 className="animate-spin text-green-600" /></div>;

  const filteredConfigs = projectFiles?.config_files?.filter((f: any) => f.category !== 'project_specific_color_checker') || [];
  const projectCheckers = projectFiles?.config_files?.filter((f: any) => f.category === 'project_specific_color_checker') || [];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
      <input type="file" ref={filesInputRef} className="hidden" multiple onChange={handleMultiFileChange} accept=".jpg,.jpeg,.png" />

      {/* 1. Project Configuration Section (Singletons) */}
      <section className="bg-neutral-900 border border-neutral-800 rounded-xl overflow-hidden">
        <div className="px-4 py-3 border-b border-neutral-800 bg-neutral-800/30 flex items-center justify-between">
          <span className="text-xs font-bold uppercase tracking-wider text-neutral-400">Standard Project References</span>
        </div>
        <div className="p-4 divide-y divide-neutral-800/50">
          {filteredConfigs.map((file: any) => (
            <div key={file.key} className="py-4 flex items-center justify-between group">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-neutral-950 rounded-lg border border-neutral-800 overflow-hidden flex items-center justify-center shrink-0 shadow-inner">
                  {file.exists || file.category === 'ideal_checker' ? (
                    <img src={getFullUrl(file.rel_path, file.category)} alt="Preview" className="w-full h-full object-contain p-1" />
                  ) : (
                    <div className="text-[10px] text-neutral-700 font-bold uppercase">No File</div>
                  )}
                </div>
                <div className="flex flex-col">
                  <span className="text-sm font-bold text-neutral-200">{file.label}</span>
                  <span className="text-[10px] text-neutral-500 font-mono truncate max-w-xs" title={file.rel_path}>{file.rel_path}</span>
