                    const newOrder = [...projectFiles.masking.order];
                    [newOrder[i], newOrder[i+1]] = [newOrder[i+1], newOrder[i]];
                    updateMaskingMutation.mutate({ order: newOrder });
                  }}
                  className="p-0.5 hover:bg-neutral-800 rounded text-neutral-600 disabled:opacity-0"
