                  className="w-full h-full object-contain p-1"
                />
              </div>

              {/* Meta */}
              <div className="flex-1 min-w-0">
                <input 
                  type="text" 
                  value={layer.label}
                  onChange={(e) => {
                    const newLayers = [...projectFiles.masking.layers];
                    newLayers[i].label = e.target.value;
                    updateMaskingMutation.mutate({ layers: newLayers });
                  }}
                  className="bg-transparent border-0 border-b border-transparent focus:border-green-600/50 focus:outline-none text-xs font-bold text-neutral-200 w-full mb-0.5"
                />
                <div className="text-[9px] font-mono text-neutral-600 truncate">{layer.filename}</div>
              </div>

              {/* Active Toggle */}
              <button 
                onClick={() => {
                  const newLayers = [...projectFiles.masking.layers];
                  newLayers[i].active = !newLayers[i].active;
                  updateMaskingMutation.mutate({ layers: newLayers });
                }}
                className={`px-2 py-1 rounded text-[9px] font-bold border transition-all ${layer.active 
                  ? 'bg-green-600/10 border-green-600/20 text-green-500' 
                  : 'bg-neutral-800 border-neutral-700 text-neutral-500'}`}
              >
                {layer.active ? 'ACTIVE' : 'INACTIVE'}
              </button>

              {/* Delete */}
              <button 
                onClick={() => {
                  if (confirm(`Delete mask layer ${layer.label}?`)) {
                    deleteMaskLayerMutation.mutate(i);
                  }
                }}
                className="p-1.5 hover:bg-red-600/10 text-neutral-600 hover:text-red-500 rounded transition-colors"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            </div>
          );
        })}
        {(!projectFiles.masking?.layers || projectFiles.masking.layers.length === 0) && (
          <div className="text-center py-4 bg-neutral-950/30 rounded-xl border border-neutral-800/50 border-dashed text-[10px] text-neutral-600 uppercase font-bold tracking-widest italic">
            No modular mask layers registered
          </div>
        )}
      </div>
    </div>
  </div>
</section>

