        <button
          onClick={() => handleUploadClick('drawing_layer')}
          className="flex items-center gap-1 text-[10px] bg-neutral-800 hover:bg-neutral-700 text-neutral-300 px-3 py-1.5 rounded-lg font-bold transition-all border border-neutral-700 shadow-sm"
        >
          <Plus className="w-3 h-3" /> ADD MASK LAYER
